import{c as t,Q as r,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const s="/assets/docs-two-cards-record-menu.PvaEVkwC.png",n="/assets/docs-two-cards-recorded.pgQjMpER.png",d="/assets/docs-two-cards-card1-mp.Ha2Zw21t.png",h="/assets/docs-two-cards-card2-ok.5rAsSPL9.png",i="/assets/docs-two-cards-both-reads.B4q2TPLJ.png",c="/assets/docs-two-cards-missed-merged.CsGWEsFt.png",l="/assets/docs-two-cards-download-tab.20ZTdCkN.png",g="/assets/docs-two-cards-better-read.DWs9sn1p.png",v=JSON.parse('{"title":"Competitors carrying two cards","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/two-cards.md","filePath":"user/running-the-event/two-cards.md"}'),u={name:"user/running-the-event/two-cards.md"};function p(m,e,w,f,b,y){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="competitors-carrying-two-cards" tabindex="-1">Competitors carrying two cards <a class="header-anchor" href="#competitors-carrying-two-cards" aria-label="Permalink to &quot;Competitors carrying two cards&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators at the download desk, and organisers deciding how a two-card event should run.</p><p>Some runners carry two cards and punch both at every control, so that a card that fails or falls off doesn&#39;t cost them their run. It&#39;s common at championships and elite races. meshO treats both cards as theirs: either card, or both, can be read, and the result comes from whatever was read.</p><h2 id="the-whole-job" tabindex="-1">The whole job <a class="header-anchor" href="#the-whole-job" aria-label="Permalink to &quot;The whole job&quot;">​</a></h2><ol><li><strong>Before they run</strong>, record the second card on the competitor: in <strong>Edit competitor</strong>, click the small card button beside <strong>Card number</strong>, type the second card&#39;s number and <strong>Save</strong>.</li><li><strong>When they come back</strong>, read their first card. Read the second card only if the first is a <strong>Missing punch</strong>.</li><li><strong>Check the result.</strong> There&#39;s nothing to assign: every read goes to the runner, and the result is worked out from both cards.</li></ol><p>That&#39;s it for almost every runner. The rest of this page shows what you&#39;ll see in each situation, and what to do when one comes up.</p><h2 id="recording-the-second-card" tabindex="-1">Recording the second card <a class="header-anchor" href="#recording-the-second-card" aria-label="Permalink to &quot;Recording the second card&quot;">​</a></h2><p>Open the competitor from the competitor list, the dashboard or the download page. Beside <strong>Card number</strong> is a small card button, greyed out while there is no second card. Click it, type the number, and click <strong>Save</strong>.</p><p><img src="'+s+'" alt="Edit competitor for Kai Novak, card 8217445, with the second card menu open and 7514206 typed in"></p><p>Once saved, the button is filled in, its tooltip names the second card, and the header reads <strong>Card 8217445 + 7514206</strong>.</p><p><img src="'+n+'" alt="Kai Novak&#39;s record after saving: the header chip shows both cards"></p><p><strong>What to do:</strong> nothing more. If the runner is in <strong>Settings → Competitors</strong>, record the second card there too, and it comes with them into every event they enter.</p><p>meshO refuses a second card that&#39;s the same as their first, or that another entry already holds.</p><h2 id="what-each-situation-looks-like" tabindex="-1">What each situation looks like <a class="header-anchor" href="#what-each-situation-looks-like" aria-label="Permalink to &quot;What each situation looks like&quot;">​</a></h2><table tabindex="0"><thead><tr><th>They bring back</th><th>What you see</th><th>Result</th></tr></thead><tbody><tr><td>Both cards, both fine</td><td>Two reads, both theirs</td><td><strong>OK</strong>, on the first card&#39;s times</td></tr><tr><td>Both cards, the first failed partway</td><td>The first read is a <strong>Missing punch</strong>; the second turns it <strong>OK</strong></td><td><strong>OK</strong></td></tr><tr><td>Only the second card</td><td>One read, theirs</td><td><strong>OK</strong>, on the second card&#39;s times</td></tr><tr><td>Both cards, each missed a different control</td><td>Each read alone is a <strong>Missing punch</strong></td><td><strong>OK</strong> by default (see <a href="#choosing-how-the-result-is-worked-out">Choosing how the result is worked out</a>)</td></tr><tr><td>Both cards, both missed the same control</td><td>Both reads are a <strong>Missing punch</strong></td><td><strong>Missing punch</strong>: they really did miss it</td></tr></tbody></table><p>The sections below go through them one at a time.</p><h2 id="the-first-card-failed-partway-round" tabindex="-1">The first card failed partway round <a class="header-anchor" href="#the-first-card-failed-partway-round" aria-label="Permalink to &quot;The first card failed partway round&quot;">​</a></h2><p>Kai Novak&#39;s first card stopped recording partway round: it has controls 100 and 31, and nothing after. Read on its own, it&#39;s a <strong>Missing punch</strong>:</p><p><img src="'+d+'" alt="The download panel after reading card 8217445: Missing punch, Kai Novak, controls 101 and 32 are missing"></p><p><strong>What to do:</strong> nothing yet. A mis-punch that ends in an unbroken run of missing controls looks like a failed card, not a wrong turn. Ask whether they carried a second card, and read it.</p><p>Kai&#39;s second card has every control. The moment it&#39;s read, the panel turns green, and a line under the result says it was worked out from both cards, and that the first card on its own was MP:</p><p><img src="'+h+'" alt="The download panel after reading card 7514206: OK, Kai Novak, place 3 of 34, 47:23, Both cards merged — card 8217445 alone was MP"></p><p>Both reads are now Kai&#39;s, and both rows in the list say <strong>OK</strong>, because each shows the runner&#39;s result:</p><p><img src="'+i+'" alt="The Card downloads list: 7514206 and 8217445, both Kai Novak, both OK"></p><p><strong>What to do:</strong> nothing. His card number stays 8217445: reading the second card never changes either card. If the mis-punch splits print was still waiting to print, the OK one prints in its place.</p><h2 id="which-card-to-read" tabindex="-1">Which card to read <a class="header-anchor" href="#which-card-to-read" aria-label="Permalink to &quot;Which card to read&quot;">​</a></h2><p>Read the runner&#39;s <strong>first card</strong>, the one they&#39;re entered on. If it&#39;s <strong>OK</strong>, that&#39;s their result and they&#39;re done. Only if it&#39;s a <strong>Missing punch</strong>, read their second card as well, and let it fill the gap.</p><p>Why not read both every time? Reading a card takes time, and at a busy finish every read is somebody else waiting in the queue. For almost every runner both cards worked, so reading the second card too would slow the queue down to change nothing.</p><p>It doesn&#39;t matter if a runner gets it the other way round. If they put their second card in first, it&#39;s matched to them and gives their result on its own; reading their first card afterwards is fine, and so is not reading it at all. If both cards are read and both worked, the second read changes nothing in the result: the panel shows the same result again, with the line <strong>Both cards merged — card … alone was OK</strong>. Their time comes from the first card, and no second splits print comes out: a read that changes nothing prints nothing.</p><p><strong>What to do:</strong> nothing beyond reading both. Each card shows in the downloads list with the runner&#39;s name.</p><h2 id="only-the-second-card-comes-back" tabindex="-1">Only the second card comes back <a class="header-anchor" href="#only-the-second-card-comes-back" aria-label="Permalink to &quot;Only the second card comes back&quot;">​</a></h2><p>If the first card was lost, or left at home after the race, read the second one. It&#39;s matched to the runner by its number, and the panel shows their result as it would for their first card.</p><p><strong>What to do:</strong> nothing. The result stands on the second card&#39;s times. If the first card turns up later and is read, it joins the second, and the result is worked out from both.</p><h2 id="each-card-missed-a-different-control" tabindex="-1">Each card missed a different control <a class="header-anchor" href="#each-card-missed-a-different-control" aria-label="Permalink to &quot;Each card missed a different control&quot;">​</a></h2><p>Sometimes neither card has everything. Wilhelm Norton&#39;s first card has no punch at control 31, and his second has none at control 101. Each read on its own is a <strong>Missing punch</strong>. Read together, though, the two cards have every control, so once the second is read he&#39;s <strong>OK</strong>:</p><p><img src="'+c+'" alt="Edit competitor for Wilhelm Norton, Downloads tab: card 8977408 + 7514209, OK, with Both cards merged chosen"></p><p><strong>What to do:</strong> decide whether that&#39;s what your event wants. By default meshO combines the two cards into one run, which is how most organisers think of a backup card. If your rules say each card has to stand on its own, change it for that runner (next section).</p><h2 id="choosing-how-the-result-is-worked-out" tabindex="-1">Choosing how the result is worked out <a class="header-anchor" href="#choosing-how-the-result-is-worked-out" aria-label="Permalink to &quot;Choosing how the result is worked out&quot;">​</a></h2><p>Open the competitor and go to <strong>Download</strong>. Once reads of both cards are held, <strong>Result from</strong> appears, with two choices:</p><p><img src="'+l+'" alt="Edit competitor, Downloads tab, for Kai Novak: the read of 8217445, a picker to switch reads, and Result from with Both cards merged chosen"></p><ul><li><strong>Both cards merged</strong> (the default). One run from both cards. Where both punched a control, the first card&#39;s punch counts; the second card fills the gaps.</li><li><strong>The better read.</strong> Each card is scored on its own, and the better result counts. If they score the same, the first card counts. When a card is read, the panel says which one was used, such as <strong>Second card used — first card 8217445 was MP</strong>, or <strong>Not used — their other card 7514206 is OK</strong> for a read that doesn&#39;t count.</li></ul><p>Switching takes effect straight away. For Wilhelm, <strong>The better read</strong> makes him a <strong>Missing punch</strong>, because neither card on its own has every control:</p><p><img src="'+g+'" alt="Wilhelm Norton with The better read chosen: the header now says MP"></p><p><strong>What to do:</strong> leave it on <strong>Both cards merged</strong> unless your event&#39;s rules say otherwise. The choice is per runner, and you can switch back at any time.</p><p>The <strong>Select download</strong> picker above it only changes which read you&#39;re looking at. It doesn&#39;t change the result.</p><h2 id="taking-a-read-off-a-runner" tabindex="-1">Taking a read off a runner <a class="header-anchor" href="#taking-a-read-off-a-runner" aria-label="Permalink to &quot;Taking a read off a runner&quot;">​</a></h2><ul><li><strong>Unassign one read</strong> (from the downloads list, as for any read) and the other stays. The runner&#39;s result then comes from the read that&#39;s left.</li><li><strong>Take the second card off the runner</strong> (the card button, then <strong>Remove</strong>) and its read goes with it, waiting in the list to be assigned. The result comes from the first card alone.</li><li><strong>Assign a read of their other card by hand</strong>, and meshO holds it beside the one they have. It doesn&#39;t ask whether to replace their result, because nothing is replaced.</li></ul><p>A second read of the <em>same</em> card is different: that&#39;s the card being used again, and meshO asks what to do, as it would for anyone (see <a href="./card-download">Card already used</a>).</p><h2 id="when-something-doesn-t-look-right" tabindex="-1">When something doesn&#39;t look right <a class="header-anchor" href="#when-something-doesn-t-look-right" aria-label="Permalink to &quot;When something doesn&#39;t look right&quot;">​</a></h2><p><strong>The second card came up as an unknown card.</strong> It wasn&#39;t recorded on the runner when it was read. Record it now (see <a href="#recording-the-second-card">Recording the second card</a>). If the runner already has their first card&#39;s read, the waiting read of the second card is picked up as soon as you save. If they don&#39;t, assign it to them from the downloads list.</p><p><strong>&quot;Card … is already held by &quot;…&quot;, so it cannot be a second card.&quot;</strong> Two entries can&#39;t share a card. Check which runner it really belongs to, and take it off the other one first.</p><p><strong>The result didn&#39;t change after the second card was read.</strong> Both cards probably missed the same control. Open <strong>Download</strong>, switch between the two reads with <strong>Select download</strong>, and compare their punches.</p><h2 id="how-the-merge-works" tabindex="-1">How the merge works <a class="header-anchor" href="#how-the-merge-works" aria-label="Permalink to &quot;How the merge works&quot;">​</a></h2><p>For readers who want the detail.</p><ul><li><strong>The first card is the record.</strong> It&#39;s the card the runner is entered on, whichever was read first. Their start, finish and check come from it when it has them, and from the second card only when it doesn&#39;t.</li><li><strong>A punch on both cards counts once.</strong> When both cards punched the same control within 30 seconds of each other, the first card&#39;s punch is used. A second-card punch of a control the first card doesn&#39;t have fills the gap.</li><li><strong>Radio punches follow the same rule.</strong> Radio punches from either card are the runner&#39;s, and where both cards punched the same control, the first card&#39;s time is used. So the live results and the downloaded result agree.</li><li><strong>The merged run isn&#39;t stored.</strong> Both reads are kept exactly as they were read, and the result is worked out from them each time. Changing <strong>Result from</strong>, a course, or an override recalculates it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./card-download">Downloading cards</a></li><li><a href="./resolving-issues#lost-cards-and-shared-cards">Lost cards and shared cards</a></li><li><a href="./radio-punches">Radio punches</a></li></ul>',57)])])}const T=t(u,[["render",p]]);export{v as __pageData,T as default};
